							local function fn93(arg3)
								local animator = arg3:FindFirstChildWhichIsA("Animator") or Instance.new("Animator", arg3)
								local animation = Instance.new("Animation")
								animation.AnimationId = animationId
								v8 = animator:LoadAnimation(animation)
								v8.Priority = Enum.AnimationPriority.Movement
								v8:AdjustSpeed(6)
								v8:Play()

